const DefaultMaxOutputTokens = 2048

func configMaxTokens(config map[string]interface{}) (int, bool) {
	if config == nil { return 0, false }
	switch v := config["max_tokens"].(type) {
	case int:        if v > 0 { return v, true }
	case int64:      if v > 0 { return int(v), true }
	case float64:    if v > 0 { return int(v), true }
	case json.Number: if n, err := v.Int64(); err == nil && n > 0 { return int(n), true }
	}
	return 0, false
}

// anthropic/gemini policy: chosen wins, else the fleet floor. Ollama does NOT use this.
func resolvedMaxTokens(config map[string]interface{}) int {
	if mt, ok := configMaxTokens(config); ok { return mt }
	return DefaultMaxOutputTokens
}

type AnthropicClient struct { apiKey, model string; maxTokens int; httpClient *http.Client }

